Method.Implementation:
Set tSC= $$$OK $$$TRACE(" Inside InvokePostService ")
try { set httpBodyData = pInput.Read(.len,.status) $$$TRACE(" httpBody : "_httpBodyData)
set httpBodyParamsList = $LISTFROMSTRING(httpBodyData, "&") Set n = $ListLength(httpBodyParamsList) Set firstName="" Set lastName="" Set msprId="" Set posId="" Set personId="" For i=1:1:n { $$$TRACE("httpBodyParamsList("_i_")::"_$List(httpBodyParamsList,i)) Set piece = $LISTFROMSTRING($List(httpBodyParamsList,i),"=") if ($LIST(piece,1)="MSPRID"){ Set msprId=$LIST(piece,2) $$$TRACE("MSPR ID : "_msprId) } if ($LIST(piece,1)="PersonID"){ Set personId=$LIST(piece,2) $$$TRACE("personId ID: "_personId) } if ($LIST(piece,1)="PositionCD"){ Set posId=$LIST(piece,2) $$$TRACE("PositionID : "_posId) } if ($LIST(piece,1)="FirstName"){ Set firstName=$LIST(piece,2) $$$TRACE("First Name : "_firstName) } if ($LIST(piece,1)="LastName"){ Set lastName=$LIST(piece,2) $$$TRACE("Last Name : "_lastName) } }
$$$TRACE("creating response object ****") Set pResponse=##class(IHC.ITF.Response.VyncaRoleDataResponse).%New() Set pResponse.MSPRID = msprId Set pResponse.PersonID = personId Set pResponse.PositionCD = posId Set pResponse.FirstName = firstName Set pResponse.LastName = lastName
$$$TRACE("***SendRequestAsync : Before ****")
do ..SendRequestAsync(..TargetConfigNames,pResponse)
$$$TRACE("***SendRequestAsync ****")
}catch e { $$$TRACE(" Unknown Exception: " _ e) set errTxt = $System.Status.GetErrorText("Unknown Exception while receiving post request per Vynca role change. "_e) Set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(..%ConfigName,errTxt) set tSC = $$$OK
} quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
